{
  "correction_rules": [
    "Reduce forecast bias when sentiment is negative (sentiment < 0) — model tends to overestimate prices.",
    "Adjust downward for long-term (30-day) forecasts when recent prices show strong mean reversion or downward momentum.",
    "Apply a lag correction: if true outcome is significantly lower than forecast, reduce next period’s forecast by 5–10% to account for delayed price adjustment.",
    "Cap forecast spikes above 75% of historical max in 15-day window to prevent overshoot after sentiment spikes.",
    "When sentiment is positive (sentiment > 0), slightly increase forecast baseline by 2–5% to reflect bullish momentum.",
    "For forecasts with high volatility (e.g., >15% deviation from true outcome), apply smoothing: average with prior 3-day forecast to reduce noise."
  ]
}
